<div class="personal-voucher-grid"><?php foreach($vmState['cards']['rows']??[]as$vmCard):$vmOpen=$vmCard['display_state']==='active'&&(int)$vmCard['remaining']>0;$vmCanRedeem=$vmState['cards']['can_redeem']&&$vmDisplay['available']&&$vmCard['consistent'];?><article class="personal-voucher-card" data-voucher-card data-card-identity="<?= e($vmCard['ticket_id']?:$vmCard['id']) ?>"><h3><?= e($vmCard['label']) ?></h3><p><?= e($vmCard['name']) ?></p><p><strong><?= e($vmAmount((int)$vmCard['remaining'],$vmCard['unit'])) ?></strong> · <?= e($vmI(['active'=>'Verfügbar','redeemed'=>'Bereits eingelöst','revoked'=>'Gesperrt'][$vmCard['display_state']])) ?></p>
<?php if($vmCard['unit']==='piece'):?><p><?= e($vmF('Einzelgutschein {number} von {count}',['number'=>$vmCard['ticket_number'],'count'=>$vmCard['ticket_total']])) ?></p><?php endif ?>
