<?php if($vmOpen):foreach(['event-voucher-redeem'=>'Gutschein einlösen','event-voucher-revoke'=>'Gutschein sperren','event-voucher-delete'=>'Gutschein ungültig machen']as$vmAction=>$vmActionLabel):if(($vmAction==='event-voucher-redeem'&&!$vmCanRedeem)||($vmAction!=='event-voucher-redeem'&&!$vmState['access']['manage']))continue;$vmDraft=\Kulturhus\Verein\EventVoucherDraft::create($vmAction,$vmEventId,(string)$vmCard['version']);$vmDraft['values']=['voucher_id'=>$vmCard['id'],'ticket_id'=>$vmCard['ticket_id']];if($vmCard['unit']==='piece')$vmDraft['values']['amount']='1';$vmTarget=$vmCard;$vmOperationRestored=false;?><details data-voucher-card-action="<?= e($vmAction) ?>"><summary><?= e($vmI($vmActionLabel)) ?></summary><?php require __DIR__.'/manage-voucher-operation.php'; ?></details><?php endforeach;endif ?>
</article><?php endforeach ?></div>
